package com.rpb.reservation.cards.entitlement;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.rpb.reservation.cards.application.*;
import com.rpb.reservation.cards.application.CardDtos.*;
import com.rpb.reservation.common.scope.StoreScope;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
@Repository
public class CardHoldingRepository {
 private final JdbcTemplate jdbc;private final ObjectMapper json;private final CardDailyExpiryRepository expiry;
 public CardHoldingRepository(JdbcTemplate jdbc,ObjectMapper json,CardDailyExpiryRepository expiry){this.jdbc=jdbc;this.json=json;this.expiry=expiry;}
 public void settle(StoreScope s,UUID customer,Instant now){expiry.settleScope(s,customer,now);}
 public void expireRestoredUse(StoreScope s,UUID id,LocalDate day,int qty,UUID original,Instant now){expiry.expireRestoredUse(s,id,day,qty,original,now);}
 public Holding get(StoreScope s,UUID id,boolean lock,Instant now){if(lock)expiry.settleCard(s,id,now);return jdbc.query("select * from customer_cards where tenant_id=? and store_id=? and id=?"+(lock?" for update":""),(r,n)->map(s,r,now),s.tenantId().value(),s.storeId().value(),id).stream().findFirst().orElseThrow(CardException::missing);}
 public List<Holding> list(StoreScope s,UUID customer,Instant now){return list(s,customer,now,null);}
 public List<Holding> list(StoreScope s,UUID customer,Instant now,UUID before){expiry.settleScope(s,customer,now);var args=new ArrayList<Object>(List.of(s.tenantId().value(),s.storeId().value()));String where="";if(customer!=null){where+=" and customer_id=?";args.add(customer);}if(before!=null){where+=" and (created_at,id)<(select created_at,id from customer_cards where tenant_id=? and store_id=? and id=?)";args.add(s.tenantId().value());args.add(s.storeId().value());args.add(before);}return jdbc.query("select * from customer_cards where tenant_id=? and store_id=?"+where+" order by created_at desc,id desc limit 500",(r,n)->map(s,r,now),args.toArray());}
 public Optional<Holding> enrollment(StoreScope s,UUID customer,UUID plan,Instant now){return jdbc.query("select * from customer_cards where tenant_id=? and store_id=? and customer_id=? and plan_id=? and kind='stamp'",(r,n)->map(s,r,now),s.tenantId().value(),s.storeId().value(),customer,plan).stream().findFirst();}
 public void enrollmentLock(StoreScope s,UUID customer,UUID plan){jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))","enroll:"+s.tenantId().value()+customer+plan);}
 public Holding issue(StoreScope s,UUID customer,Plan p,String kind,Integer total,Integer daily,String zone,Instant now,Instant expiry){UUID id=UUID.randomUUID();jdbc.update("insert into customer_cards(id,tenant_id,store_id,customer_id,plan_id,kind,remaining,initial_total,daily_limit,timezone,starts_at,expires_at,snapshot,daily_expiry_from,daily_expiry_next_day) values(?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?)",id,s.tenantId().value(),s.storeId().value(),customer,p.id(),kind,total,total,daily,zone,Timestamp.from(now),Timestamp.from(expiry),encode(p),java.sql.Date.valueOf(CardRules.day(now,zone)),java.sql.Date.valueOf(CardRules.day(now,zone)));return get(s,id,false,now);}
 public void update(StoreScope s,Holding h,Integer remaining,int progress,int round){jdbc.update("update customer_cards set remaining=?,progress=?,round=?,version=version+1,updated_at=now() where tenant_id=? and store_id=? and id=?",remaining,progress,round,s.tenantId().value(),s.storeId().value(),h.id());}
 public void status(StoreScope s,UUID id,String status){jdbc.update("update customer_cards set status=?,version=version+1,updated_at=now() where tenant_id=? and store_id=? and id=?",status,s.tenantId().value(),s.storeId().value(),id);}
 public int used(StoreScope s,UUID card,LocalDate day){return jdbc.query("select used from card_daily_usage where tenant_id=? and card_id=? and day=?",(r,n)->r.getInt(1),s.tenantId().value(),card,java.sql.Date.valueOf(day)).stream().findFirst().orElse(0);}
 public void usage(StoreScope s,UUID card,LocalDate day,int delta){if(delta<0){if(jdbc.update("update card_daily_usage set used=used+? where tenant_id=? and card_id=? and day=? and used>=?",delta,s.tenantId().value(),card,java.sql.Date.valueOf(day),-delta)!=1)throw CardException.conflict("原日额度不能重复恢复");return;}jdbc.update("insert into card_daily_usage(tenant_id,card_id,day,used) values(?,?,?,?) on conflict(tenant_id,card_id,day) do update set used=card_daily_usage.used+excluded.used",s.tenantId().value(),card,java.sql.Date.valueOf(day),delta);}
 public UUID entry(StoreScope s,Holding h,String kind,int qty,Integer before,Integer after,LocalDate day,int beforeDay,int afterDay,String source,UUID original,UUID actor,UUID confirmed,String reason,Instant now){UUID id=UUID.randomUUID();jdbc.update("insert into card_entries(id,tenant_id,store_id,card_id,customer_id,plan_id,kind,quantity,before_total,after_total,business_day,before_daily,after_daily,source,original_id,actor_id,confirmed_by,reason,created_at,stamp_reward_round) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,s.tenantId().value(),s.storeId().value(),h.id(),h.customerId(),h.planId(),kind,qty,before,after,java.sql.Date.valueOf(day),beforeDay,afterDay,source,original,actor,confirmed,reason==null?"":reason,Timestamp.from(now),kind.equals("stamp")&&after!=null&&after==0?h.round()+1:null);return id;}
 public Entry entry(StoreScope s,UUID id){return jdbc.query("select * from card_entries where tenant_id=? and store_id=? and id=?",this::entryMap,s.tenantId().value(),s.storeId().value(),id).stream().findFirst().orElseThrow(CardException::missing);}
 public List<Entry> entries(StoreScope s,UUID customer){return entries(s,customer,null);}
 public List<Entry> entries(StoreScope s,UUID customer,UUID before){var args=new ArrayList<Object>(List.of(s.tenantId().value(),s.storeId().value()));String where="";if(customer!=null){where+=" and customer_id=?";args.add(customer);}if(before!=null){where+=" and entry_sequence<(select entry_sequence from card_entries where tenant_id=? and store_id=? and id=?)";args.add(s.tenantId().value());args.add(s.storeId().value());args.add(before);}return jdbc.query("select * from card_entries where tenant_id=? and store_id=?"+where+" order by entry_sequence desc limit 500",this::entryMap,args.toArray());}
 public boolean reversed(StoreScope s,UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from card_entries where tenant_id=? and original_id=?)",Boolean.class,s.tenantId().value(),id));}
 public UUID latestStamp(StoreScope s,UUID card){return jdbc.query("select e.id from card_entries e where e.tenant_id=? and e.card_id=? and e.kind='stamp' and not exists(select 1 from card_entries x where x.tenant_id=e.tenant_id and x.original_id=e.id) order by e.entry_sequence desc limit 1",(r,n)->r.getObject(1,UUID.class),s.tenantId().value(),card).stream().findFirst().orElseThrow(CardException::missing);}
 public boolean liveReward(StoreScope s,UUID card){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from card_reward_grants g join customer_cards c on c.tenant_id=g.tenant_id and c.id=g.reward_card_id where g.tenant_id=? and g.card_id=? and c.status<>'revoked')",Boolean.class,s.tenantId().value(),card));}
 public boolean hasRedemptions(StoreScope s,UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from card_entries where tenant_id=? and card_id=? and kind='redeem')",Boolean.class,s.tenantId().value(),id));}
 public void reward(StoreScope s,UUID card,int round,UUID reward){jdbc.update("insert into card_reward_grants(tenant_id,card_id,round,reward_card_id) values(?,?,?,?)",s.tenantId().value(),card,round,reward);}
 public List<UUID> rewards(StoreScope s,UUID card,int round){return jdbc.query("select reward_card_id from card_reward_grants where tenant_id=? and card_id=? and round=?",(r,n)->r.getObject(1,UUID.class),s.tenantId().value(),card,round);}
 public boolean sourceExists(StoreScope s,UUID plan,String source){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from card_entries where tenant_id=? and plan_id=? and kind='stamp' and source=?)",Boolean.class,s.tenantId().value(),plan,source));}
 private Holding map(StoreScope s,ResultSet r,Instant now)throws SQLException{try{Plan p=json.readValue(r.getString("snapshot"),Plan.class);String zone=r.getString("timezone");int used=used(s,r.getObject("id",UUID.class),CardRules.day(now,zone));Integer remaining=(Integer)r.getObject("remaining"),daily=(Integer)r.getObject("daily_limit");Instant start=r.getTimestamp("starts_at").toInstant(),expiry=r.getTimestamp("expires_at").toInstant();String status=r.getString("status");int available=status.equals("active")&&!now.isBefore(start)&&now.isBefore(expiry)?CardRules.available(remaining,daily,used):0;return new Holding(r.getObject("id",UUID.class),r.getObject("customer_id",UUID.class),r.getObject("plan_id",UUID.class),r.getString("kind"),remaining,(Integer)r.getObject("initial_total"),daily,r.getInt("progress"),r.getInt("round"),zone,start,expiry,status,r.getInt("version"),p,used,available);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
 private Entry entryMap(ResultSet r,int n)throws SQLException{return new Entry(r.getObject("id",UUID.class),r.getObject("card_id",UUID.class),r.getObject("customer_id",UUID.class),r.getString("kind"),r.getInt("quantity"),(Integer)r.getObject("before_total"),(Integer)r.getObject("after_total"),r.getDate("business_day").toLocalDate(),r.getInt("before_daily"),r.getInt("after_daily"),r.getString("source"),r.getObject("original_id",UUID.class),r.getString("reason"),r.getTimestamp("created_at").toInstant(),(Integer)r.getObject("stamp_reward_round"));}
 private String encode(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
}
